<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyon mesajları</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:800px;margin:35px auto;padding:0 18px}.panel{background:white;border:1px solid #e7ece8;border-radius:14px;padding:20px;margin:12px 0}.msg{padding:12px;border-radius:10px;background:#f0f5f1;margin:10px 0;max-width:80%}.mine{margin-left:auto;background:#e6f2eb}textarea{width:100%;box-sizing:border-box;min-height:90px;padding:12px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}button{background:#176b50;color:white;border:0;border-radius:8px;padding:12px 17px;font-weight:700}.muted{color:#6d796f;font-size:13px}</style></head><body><main class="wrap"><h1><?= e($booking['title']) ?> · Mesajlaşma</h1><p class="muted"><?= e($booking['booking_code']) ?> · <?= e($booking['guest_name']) ?></p><section class="panel"><?php foreach($messages as $message): ?><div class="msg <?= (int)$message['sender_user_id']===(int)$user['id']?'mine':'' ?>"><strong><?= (int)$message['sender_user_id']===(int)$user['id']?'Siz':e($message['sender_name']) ?></strong><p><?= nl2br(e($message['body'])) ?></p><small class="muted"><?= e($message['created_at']) ?></small></div><?php endforeach; ?><?php if(!$messages): ?><p>Henüz mesaj yok. İlk mesajınızı gönderebilirsiniz.</p><?php endif; ?></section><form class="panel" method="post" action="/account/messages/send"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><label>Mesajınız</label><textarea name="body" maxlength="5000" required></textarea><p><button type="submit">Mesaj gönder</button></p></form><p><a href="<?= ($user['role']??'')==='vendor'?'/vendor':'/account/bookings' ?>">Geri dön</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>